@travel query
  mode select
  select ?minutes
  where duration(route_demo, ?minutes)

@known solve
  query $travel
  output ?minutes one

@departure value
  data 770

@arrival jsEval
  expr $departure + $minutes

@limit constraint
  var ?time int 0 1440
  require ?time == $arrival
  claim ?time <= 840
  task possible

@r solve
  constraint $limit
  output ?time one

@answer cnl
  result $r
  language en

